using System.Windows; using ANLAbel.App.ViewModels; using ANLAbel.Core.Scene; using ANLAbel.Core.Workflow;
namespace ANLAbel.App; public partial class DocumentWorkflowWindow:Window { private readonly DocumentWorkflowViewModel _vm; public DocumentWorkflowWindow(MainViewModel main):this(main.CurrentFilePath,()=>DocumentSnapshot.Capture(main.Template).DocumentHash){} public DocumentWorkflowWindow(string path,Func<string> hash){InitializeComponent();_vm=new DocumentWorkflowViewModel(path,hash);DataContext=_vm;} private void Refresh_Click(object s,RoutedEventArgs e)=>_vm.Refresh(); private void Transition_Click(object s,RoutedEventArgs e){if((s as FrameworkElement)?.Tag is DocumentWorkflowTransition t)_vm.Transition(t);} private void Close_Click(object s,RoutedEventArgs e)=>Close(); }
